]$pge$::jsonb) AS r(year integer,section_code text,section_name text,program_code text,program_name text,
 economic_chapter integer,credit_initial numeric,source_csv text,source_sha256 text,ministry_normalized text)),
links AS (SELECT r.*,e.folder,
 'https://www.sepg.pap.hacienda.gob.es/Presup/'||e.folder||'/MaestroDocumentos/PGE-ROM/Indice.htm' AS edition_index_url,
 'https://www.sepg.pap.hacienda.gob.es/Presup/'||e.folder||'/MaestroDocumentos/PGE-ROM/doc/CSV/'||r.source_csv AS source_url
 FROM raw r JOIN editions e USING(year))
SELECT year,section_code,section_name,program_code,program_name,economic_chapter,credit_initial,
 'prorroga'::text AS budget_type,'published_prorroga'::text AS source_kind,year AS source_year,2023 AS in_force_year,
 NULL::text AS service_code,NULL::text AS service_name,NULL::text AS economic_article,NULL::text AS economic_concept,
 NULL::numeric AS credit_final,ministry_normalized,'state'::text AS administration_level,source_url,
 jsonb_build_object('source','SEPG ROM prorroga, folder='||folder||', PGE en vigor=2023',
 'budget_type','prorroga','source_kind','published_prorroga','in_force_year',2023,'edition_index_url',edition_index_url,
 'verified_exercise',year,'source_sha256',source_sha256,'section_code',section_code,'program_code',program_code,
 'economic_chapter',economic_chapter) AS raw_data FROM links;
DO $$ BEGIN
 IF (SELECT count(*) FROM audited_pge) <> 4001 THEN RAISE EXCEPTION 'Incomplete PGE snapshot'; END IF;
 IF EXISTS (SELECT 1 FROM audited_pge WHERE credit_initial IS NULL OR source_kind <> 'published_prorroga'
   OR source_url IS NULL OR raw_data->>'source_sha256' IS NULL) THEN RAISE EXCEPTION 'Missing PGE provenance'; END IF;
END $$;
INSERT INTO budget_lines (year,budget_type,source_kind,source_year,in_force_year,section_code,section_name,
 service_code,service_name,program_code,program_name,economic_chapter,economic_article,economic_concept,
 credit_initial,credit_final,ministry_normalized,administration_level,source_url,raw_data)
SELECT year,budget_type,source_kind,source_year,in_force_year,section_code,section_name,
 service_code,service_name,program_code,program_name,economic_chapter,economic_article,economic_concept,
 credit_initial,credit_final,ministry_normalized,administration_level,source_url,raw_data FROM audited_pge
ON CONFLICT (year,budget_type,section_code,program_code,economic_chapter) DO UPDATE SET
 source_kind=EXCLUDED.source_kind,source_year=EXCLUDED.source_year,in_force_year=EXCLUDED.in_force_year,
 section_name=EXCLUDED.section_name,program_name=EXCLUDED.program_name,credit_initial=EXCLUDED.credit_initial,
 credit_final=EXCLUDED.credit_final,ministry_normalized=EXCLUDED.ministry_normalized,
 source_url=EXCLUDED.source_url,raw_data=EXCLUDED.raw_data,updated_at=now();
DELETE FROM budget_lines bl WHERE year IN (2024,2025,2026) AND budget_type='prorroga'
 AND source_kind <> 'carried_forward'
 AND NOT EXISTS (SELECT 1 FROM audited_pge p WHERE
   (p.year,p.section_code,p.program_code,p.economic_chapter)=(bl.year,bl.section_code,bl.program_code,bl.economic_chapter));
-- Historical references retain the original 2023 document, not a prorroga index.
UPDATE budget_lines reference SET source_url=original.source_url,
 raw_data=original.raw_data || jsonb_build_object('source_kind','carried_forward','budget_type','prorroga',
 'source_year',2023,'in_force_year',2023,'carried_forward',true,
 'reference_context_url',CASE reference.year
  WHEN 2024 THEN 'https://www.sepg.pap.hacienda.gob.es/Presup/PGE2023Prorroga/MaestroDocumentos/PGE-ROM/Indice.htm'
  WHEN 2025 THEN 'https://www.sepg.pap.hacienda.gob.es/Presup/PGE2024Prorroga/MaestroDocumentos/PGE-ROM/Indice.htm'
  WHEN 2026 THEN 'https://www.sepg.pap.hacienda.gob.es/Presup/PGE2025Prorroga/MaestroDocumentos/PGE-ROM/Indice.htm' END),updated_at=now()
FROM budget_lines original WHERE reference.year IN (2024,2025,2026)
 AND reference.source_kind='carried_forward' AND original.year=2023 AND original.budget_type='ley'
 AND (reference.section_code,reference.program_code,reference.economic_chapter)=
     (original.section_code,original.program_code,original.economic_chapter);
INSERT INTO etl_runs (pipeline,chunk_key,status,rows_read,finished_at)
VALUES ('presupuestos','audited-editions-2024-2026','succeeded',4001,now());
